from pathlib import Path

p=Path('studio/src/ProjectDocumentsWorkspace.tsx')
s=p.read_text()
s=s.replace("type Measurement={id:string;a:Point;b:Point;label:string;description?:string;visible:boolean;offset?:number};\ntype PageState={calibration?:Calibration;scale?:number;measurements:Measurement[]};\ntype DrawingState=Record<string,PageState>;\ntype Tool='hand'|'calibrate'|'measure';", "type Measurement={id:string;a:Point;b:Point;label:string;description?:string;visible:boolean;offset?:number};\ntype AngleMeasurement={id:string;center:Point;a:Point;b:Point;label:string;description?:string;visible:boolean;labelOffset?:Point};\ntype PageState={calibration?:Calibration;scale?:number;measurements:Measurement[];angles?:AngleMeasurement[]};\ntype DrawingState=Record<string,PageState>;\ntype Tool='hand'|'calibrate'|'measure'|'angle';")

s=s.replace("function previewPoint(point:Point|null,shift:boolean){return point&&pending.length===1?snapPoint(pending[0],point,shift):point}", "function previewPoint(point:Point|null,shift:boolean){return point&&pending.length>=1?snapPoint(pending[0],point,shift):point}\n function measuredAngle(a:AngleMeasurement){const target=isPdf?canvasRef.current:imageRef.current;if(!target)return 0;const r=target.getBoundingClientRect();const v1x=(a.a.x-a.center.x)*r.width,v1y=(a.a.y-a.center.y)*r.height,v2x=(a.b.x-a.center.x)*r.width,v2y=(a.b.y-a.center.y)*r.height;const l1=Math.hypot(v1x,v1y),l2=Math.hypot(v2x,v2y);if(!l1||!l2)return 0;const c=Math.max(-1,Math.min(1,(v1x*v2x+v1y*v2y)/(l1*l2)));return Math.acos(c)*180/Math.PI}")

old="function handleStageClick(e:React.PointerEvent<HTMLDivElement>){if(tool==='hand'||!attachment)return;let point=pointFromEvent(e);if(!point)return;if(pending.length===1)point=snapPoint(pending[0],point,e.shiftKey);const next=[...pending,point];if(next.length<2){setPending(next);return}setPending([]);if(tool==='calibrate'){const raw=window.prompt('Ange verkligt avstånd mellan punkterna i mm:','1000');if(!raw)return;const distanceMm=Number(raw.replace(',','.'));if(!Number.isFinite(distanceMm)||distanceMm<=0){setMessage('Ogiltigt kalibreringsmått.');return}updatePage({...pageState,calibration:{a:next[0],b:next[1],distanceMm}});setTool('hand');setMessage('Skalan är kalibrerad för den här sidan.');return}if(!pageState.calibration&&!pageState.scale){setMessage('Välj ritningsskala eller kalibrera innan du mäter.');return}updatePage({...pageState,measurements:[...pageState.measurements,{id:crypto.randomUUID(),a:next[0],b:next[1],label:'',description:'',visible:true,offset:0}]});}"
new="function handleStageClick(e:React.PointerEvent<HTMLDivElement>){if(tool==='hand'||!attachment)return;let point=pointFromEvent(e);if(!point)return;if(pending.length>=1)point=snapPoint(pending[0],point,e.shiftKey);const next=[...pending,point];if(tool==='angle'){if(next.length<3){setPending(next);return}setPending([]);const angle:AngleMeasurement={id:crypto.randomUUID(),center:next[0],a:next[1],b:next[2],label:'',description:'',visible:true,labelOffset:{x:0,y:0}};if(measuredAngle(angle)<0.1){setMessage('Vinkeln är för liten för att sparas.');return}updatePage({...pageState,angles:[...(pageState.angles||[]),angle]});return}if(next.length<2){setPending(next);return}setPending([]);if(tool==='calibrate'){const raw=window.prompt('Ange verkligt avstånd mellan punkterna i mm:','1000');if(!raw)return;const distanceMm=Number(raw.replace(',','.'));if(!Number.isFinite(distanceMm)||distanceMm<=0){setMessage('Ogiltigt kalibreringsmått.');return}updatePage({...pageState,calibration:{a:next[0],b:next[1],distanceMm}});setTool('hand');setMessage('Skalan är kalibrerad för den här sidan.');return}if(!pageState.calibration&&!pageState.scale){setMessage('Välj ritningsskala eller kalibrera innan du mäter.');return}updatePage({...pageState,measurements:[...pageState.measurements,{id:crypto.randomUUID(),a:next[0],b:next[1],label:'',description:'',visible:true,offset:0}]});}"
assert old in s
s=s.replace(old,new)

marker="function removeMeasurement(id:string){updatePage({...pageState,measurements:pageState.measurements.filter(m=>m.id!==id)})}"
insert=marker+"\n function removeAngle(id:string){updatePage({...pageState,angles:(pageState.angles||[]).filter(a=>a.id!==id)})}\n function toggleAngle(id:string){updatePage({...pageState,angles:(pageState.angles||[]).map(a=>a.id===id?{...a,visible:!a.visible}:a)})}\n function editAngle(id:string,patch:Partial<Pick<AngleMeasurement,'label'|'description'>>){updatePage({...pageState,angles:(pageState.angles||[]).map(a=>a.id===id?{...a,...patch}:a)})}\n function setAngleLabelOffset(id:string,labelOffset:Point,final:boolean){if(!stateKey)return;setStates(current=>{const currentPage=current[stateKey]||{measurements:[]};const nextPage={...currentPage,angles:(currentPage.angles||[]).map(a=>a.id===id?{...a,labelOffset}:a)};const value={...current,[stateKey]:nextPage};writeState(projectId,value);if(final)void saveSharedState(projectId,value);return value})}"
assert marker in s
s=s.replace(marker,insert)

old="<button className={tool==='measure'?'active':''} onClick={()=>{setTool('measure');setPending([])}} disabled={!pageState.calibration&&!pageState.scale}>📏 Mät</button><button onClick={()=>setShowMeasurements(v=>!v)}>"
new="<button className={tool==='measure'?'active':''} onClick={()=>{setTool('measure');setPending([])}} disabled={!pageState.calibration&&!pageState.scale}>📏 Mät</button><button className={tool==='angle'?'active':''} onClick={()=>{setTool('angle');setPending([])}}>∠ Vinkel</button><button onClick={()=>setShowMeasurements(v=>!v)}>"
assert old in s
s=s.replace(old,new)

old="<DimensionOverlay targetRef={isPdf?canvasRef:imageRef} pageState={pageState} tool={tool} showMeasurements={showMeasurements} measuredMm={measuredMm} onOffsetChange={setMeasurementOffset}/><Magnifier"
new="<DimensionOverlay targetRef={isPdf?canvasRef:imageRef} pageState={pageState} tool={tool} showMeasurements={showMeasurements} measuredMm={measuredMm} onOffsetChange={setMeasurementOffset}/><AngleOverlay targetRef={isPdf?canvasRef:imageRef} angles={pageState.angles||[]} tool={tool} showMeasurements={showMeasurements} onOffsetChange={setAngleLabelOffset}/><Magnifier"
assert old in s
