oldpanel='</div><div><small>SPARADE MÅTT</small>{pageState.measurements.length?pageState.measurements.map(m=><article key={m.id} className="measurementItem"><button className="visibility" onClick={()=>toggleMeasurement(m.id)}>{m.visible?\'◉\':\'○\'}</button><span className="measurementFields"><b>{formatMm(measuredMm(m))}</b><input value={m.label||\'\'} onChange={e=>editMeasurement(m.id,{label:e.target.value})} placeholder="Namn (valfritt)"/><textarea rows={2} value={m.description||\'\'} onChange={e=>editMeasurement(m.id,{description:e.target.value})} placeholder="Beskrivning (valfri)"/></span><button className="delete" onClick={()=>removeMeasurement(m.id)}>×</button></article>):<p>Inga mått sparade på den här sidan.</p>}</div></aside>'
newpanel='</div><div><small>SPARADE MÅTT</small>{pageState.measurements.length?pageState.measurements.map(m=><article key={m.id} className="measurementItem"><button className="visibility" onClick={()=>toggleMeasurement(m.id)}>{m.visible?\'◉\':\'○\'}</button><span className="measurementFields"><b>{formatMm(measuredMm(m))}</b><input value={m.label||\'\'} onChange={e=>editMeasurement(m.id,{label:e.target.value})} placeholder="Namn (valfritt)"/><textarea rows={2} value={m.description||\'\'} onChange={e=>editMeasurement(m.id,{description:e.target.value})} placeholder="Beskrivning (valfri)"/></span><button className="delete" onClick={()=>removeMeasurement(m.id)}>×</button></article>):<p>Inga längdmått sparade på den här sidan.</p>}</div><div><small>SPARADE VINKLAR</small>{(pageState.angles||[]).length?(pageState.angles||[]).map(a=><article key={a.id} className="measurementItem"><button className="visibility" onClick={()=>toggleAngle(a.id)}>{a.visible?\'◉\':\'○\'}</button><span className="measurementFields"><b>{formatAngle(measuredAngle(a))}</b><input value={a.label||\'\'} onChange={e=>editAngle(a.id,{label:e.target.value})} placeholder="Namn (valfritt)"/><textarea rows={2} value={a.description||\'\'} onChange={e=>editAngle(a.id,{description:e.target.value})} placeholder="Beskrivning (valfri)"/></span><button className="delete" onClick={()=>removeAngle(a.id)}>×</button></article>):<p>Inga vinklar sparade på den här sidan.</p>}</div></aside>'
assert oldpanel in s
s=s.replace(oldpanel,newpanel)

angle_component='''function AngleOverlay({targetRef,angles,tool,showMeasurements,onOffsetChange}:{targetRef:React.RefObject<HTMLCanvasElement|null>|React.RefObject<HTMLImageElement|null>;angles:AngleMeasurement[];tool:Tool;showMeasurements:boolean;onOffsetChange:(id:string,offset:Point,final:boolean)=>void}){\n const[size,setSize]=useState({w:0,h:0});const dragRef=useRef<{id:string;pointerId:number}|null>(null);\n useEffect(()=>{const target=targetRef.current;if(!target)return;const update=()=>{const r=target.getBoundingClientRect();setSize({w:r.width,h:r.height})};update();const ro=new ResizeObserver(update);ro.observe(target);return()=>ro.disconnect()},[targetRef.current]);\n if(!showMeasurements||!size.w||!size.h)return null;\n const geom=(a:AngleMeasurement)=>{const cx=a.center.x*size.w,cy=a.center.y*size.h,ax=a.a.x*size.w,ay=a.a.y*size.h,bx=a.b.x*size.w,by=a.b.y*size.h;const a1=Math.atan2(ay-cy,ax-cx),a2=Math.atan2(by-cy,bx-cx);let d=a2-a1;while(d<=-Math.PI)d+=Math.PI*2;while(d>Math.PI)d-=Math.PI*2;const abs=Math.abs(d),r=Math.min(34,Math.max(18,Math.min(Math.hypot(ax-cx,ay-cy),Math.hypot(bx-cx,by-cy))*.24));const mid=a1+d/2;const endA={x:cx+Math.cos(a1)*r,y:cy+Math.sin(a1)*r},endB={x:cx+Math.cos(a2)*r,y:cy+Math.sin(a2)*r};const arc=`M ${endA.x} ${endA.y} A ${r} ${r} 0 0 ${d>=0?1:0} ${endB.x} ${endB.y}`;const off=a.labelOffset||{x:0,y:0};const lx=cx+Math.cos(mid)*(r+20)+off.x*size.w,ly=cy+Math.sin(mid)*(r+20)+off.y*size.h;return{cx,cy,ax,ay,bx,by,arc,lx,ly,deg:abs*180/Math.PI}};\n const offset=(a:AngleMeasurement,e:React.PointerEvent<SVGRectElement>)=>{const target=targetRef.current;if(!target)return a.labelOffset||{x:0,y:0};const r=target.getBoundingClientRect(),g=geom({...a,labelOffset:{x:0,y:0}});return{x:(e.clientX-r.left-g.lx)/size.w,y:(e.clientY-r.top-g.ly)/size.h}};\n return <svg width={size.w} height={size.h} style={{position:'absolute',left:0,top:0,overflow:'visible',pointerEvents:'none',zIndex:4}}>{angles.filter(a=>a.visible!==false).map(a=>{const g=geom(a),text=a.label?`${a.label} · ${formatAngle(g.deg)}`:formatAngle(g.deg),w=Math.max(38,text.length*5.8+10);return <g key={a.id}><line x1={g.cx} y1={g.cy} x2={g.ax} y2={g.ay} stroke="#d07a22" strokeWidth="1.5"/><line x1={g.cx} y1={g.cy} x2={g.bx} y2={g.by} stroke="#d07a22" strokeWidth="1.5"/><path d={g.arc} fill="none" stroke="#d07a22" strokeWidth="1.5"/><circle cx={g.cx} cy={g.cy} r="2.8" fill="#fff" stroke="#d07a22" strokeWidth="1.4"/><rect x={g.lx-w/2} y={g.ly-8} width={w} height="16" rx="3" fill="rgba(255,255,255,.86)" stroke="rgba(208,122,34,.72)"/><text x={g.lx} y={g.ly+3.2} textAnchor="middle" fontSize="9" fontWeight="600" fill="#70420c">{text}</text><rect x={g.lx-w/2-5} y={g.ly-13} width={w+10} height="26" fill="transparent" style={{pointerEvents:tool==='hand'?'all':'none',cursor:'grab'}} onPointerDown={e=>{e.stopPropagation();dragRef.current={id:a.id,pointerId:e.pointerId};e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(dragRef.current?.id!==a.id)return;e.stopPropagation();onOffsetChange(a.id,offset(a,e),false)}} onPointerUp={e=>{if(dragRef.current?.id!==a.id)return;e.stopPropagation();onOffsetChange(a.id,offset(a,e),true);dragRef.current=null}} onPointerCancel={e=>{if(dragRef.current?.id===a.id)onOffsetChange(a.id,offset(a,e),true);dragRef.current=null}}/></g>})}</svg>;\n}\n\n'''
assert "function DrawingOverlay(" in s
s=s.replace("function DrawingOverlay(",angle_component+"function DrawingOverlay(",1)

oldprev='{pending.length===1&&cursorPoint&&(()=>{const a=p(pending[0]),b=p(cursorPoint);return <g className="measurementPreview"><line x1={a.x} y1={a.y} x2={b.x} y2={b.y}/><circle cx={b.x} cy={b.y} r="4"/></g>})()}'
newprev='{pending.length>=1&&cursorPoint&&(()=>{const c=p(pending[0]),b=p(cursorPoint);if(tool===\'angle\'&&pending.length===2){const a=p(pending[1]);const v1x=a.x-c.x,v1y=a.y-c.y,v2x=b.x-c.x,v2y=b.y-c.y,l1=Math.hypot(v1x,v1y),l2=Math.hypot(v2x,v2y);const deg=l1&&l2?Math.acos(Math.max(-1,Math.min(1,(v1x*v2x+v1y*v2y)/(l1*l2))))*180/Math.PI:0;return <g className="measurementPreview"><line x1={c.x} y1={c.y} x2={a.x} y2={a.y}/><line x1={c.x} y1={c.y} x2={b.x} y2={b.y}/><circle cx={b.x} cy={b.y} r="4"/><text x={c.x+12} y={c.y-12}>{formatAngle(deg)}</text></g>}return <g className="measurementPreview"><line x1={c.x} y1={c.y} x2={b.x} y2={b.y}/><circle cx={b.x} cy={b.y} r="4"/></g>})()}'
assert oldprev in s
s=s.replace(oldprev,newprev)
s=s.replace('{tool!==\'hand\'&&pending.length===1&&<text className="pendingHint" x={p(pending[0]).x+10} y={p(pending[0]).y-10}>Välj punkt 2</text>}', '{tool!==\'hand\'&&pending.length>0&&<text className="pendingHint" x={p(pending[0]).x+10} y={p(pending[0]).y-10}>{tool===\'angle\'&&pending.length===2?\'Välj punkt 3\':\'Välj punkt 2\'}</text>}')
s=s.replace("function formatMm(value:number){if(!Number.isFinite(value))return'—';if(value>=1000)return `${(value/1000).toFixed(value>=10000?2:3).replace('.',',')} m`;return `${Math.round(value)} mm`}", "function formatMm(value:number){if(!Number.isFinite(value))return'—';if(value>=1000)return `${(value/1000).toFixed(value>=10000?2:3).replace('.',',')} m`;return `${Math.round(value)} mm`}\nfunction formatAngle(value:number){return `${value.toFixed(1).replace('.',',')}°`}")
p.write_text(s)

p=Path('src/DrawingAnnotations.tsx')
a=p.read_text()
a=a.replace("type DrawingMeasurement={id:string;a:DrawingPoint;b:DrawingPoint;label:string;description?:string;visible:boolean;offset?:number};\ntype DrawingPageState={calibration?:DrawingCalibration;scale?:number;measurements:DrawingMeasurement[]};", "type DrawingMeasurement={id:string;a:DrawingPoint;b:DrawingPoint;label:string;description?:string;visible:boolean;offset?:number};\ntype DrawingAngle={id:string;center:DrawingPoint;a:DrawingPoint;b:DrawingPoint;label:string;description?:string;visible:boolean;labelOffset?:DrawingPoint};\ntype DrawingPageState={calibration?:DrawingCalibration;scale?:number;measurements:DrawingMeasurement[];angles?:DrawingAngle[]};")
comp='''function ReadOnlyAngleOverlay({targetRef,angles}:{targetRef:React.RefObject<HTMLCanvasElement|null>|React.RefObject<HTMLImageElement|null>;angles:DrawingAngle[]}){\n  const[size,setSize]=useState({w:0,h:0});\n  useEffect(()=>{const target=targetRef.current;if(!target)return;const update=()=>{const r=target.getBoundingClientRect();setSize({w:r.width,h:r.height})};update();const ro=new ResizeObserver(update);ro.observe(target);return()=>ro.disconnect()},[targetRef.current]);\n  if(!size.w||!size.h)return null;\n  return <svg width={size.w} height={size.h} aria-hidden="true" style={{position:'absolute',left:0,top:0,overflow:'visible',pointerEvents:'none',zIndex:2}}>{angles.map(a=>{const cx=a.center.x*size.w,cy=a.center.y*size.h,ax=a.a.x*size.w,ay=a.a.y*size.h,bx=a.b.x*size.w,by=a.b.y*size.h,a1=Math.atan2(ay-cy,ax-cx),a2=Math.atan2(by-cy,bx-cx);let d=a2-a1;while(d<=-Math.PI)d+=Math.PI*2;while(d>Math.PI)d-=Math.PI*2;const deg=Math.abs(d)*180/Math.PI,r=Math.min(34,Math.max(18,Math.min(Math.hypot(ax-cx,ay-cy),Math.hypot(bx-cx,by-cy))*.24)),mid=a1+d/2,endA={x:cx+Math.cos(a1)*r,y:cy+Math.sin(a1)*r},endB={x:cx+Math.cos(a2)*r,y:cy+Math.sin(a2)*r},arc=`M ${endA.x} ${endA.y} A ${r} ${r} 0 0 ${d>=0?1:0} ${endB.x} ${endB.y}`,off=a.labelOffset||{x:0,y:0},lx=cx+Math.cos(mid)*(r+20)+off.x*size.w,ly=cy+Math.sin(mid)*(r+20)+off.y*size.h,text=[a.label,`${deg.toFixed(1).replace('.',',')}°`].filter(Boolean).join(' · '),w=Math.max(40,text.length*6+10);return <g key={a.id}><line x1={cx} y1={cy} x2={ax} y2={ay} stroke="#c56f18" strokeWidth="1.5"/><line x1={cx} y1={cy} x2={bx} y2={by} stroke="#c56f18" strokeWidth="1.5"/><path d={arc} fill="none" stroke="#c56f18" strokeWidth="1.5"/><circle cx={cx} cy={cy} r="2.8" fill="#fff" stroke="#c56f18" strokeWidth="1.4"/><rect x={lx-w/2} y={ly-9} width={w} height="18" rx="4" fill="rgba(255,255,255,.86)" stroke="rgba(197,111,24,.65)"/><text x={lx} y={ly+3.7} textAnchor="middle" fontSize="11" fontWeight="600" fill="#6d430d">{text}</text></g>})}</svg>;\n}\n\n'''
assert 'export function DrawingAnnotations' in a
a=a.replace('export function DrawingAnnotations',comp+'export function DrawingAnnotations',1)
a=a.replace("const currentMeasurements=(measurementPage?.measurements||[]).filter(item=>item.visible!==false);", "const currentMeasurements=(measurementPage?.measurements||[]).filter(item=>item.visible!==false);\n  const currentAngles=(measurementPage?.angles||[]).filter(item=>item.visible!==false);")
a=a.replace("(file.contentType==='application/pdf'&&pageCount>1||currentMeasurements.length>0)", "(file.contentType==='application/pdf'&&pageCount>1||currentMeasurements.length>0||currentAngles.length>0)")
a=a.replace("{currentMeasurements.length>0&&<button onClick={()=>setShowMeasurements(value=>!value)}>", "{(currentMeasurements.length>0||currentAngles.length>0)&&<button onClick={()=>setShowMeasurements(value=>!value)}>")
old="{showMeasurements&&currentMeasurements.length>0&&<ReadOnlyDimensionOverlay targetRef={file.contentType.startsWith('image/')?imageRef:canvasRef} measurements={currentMeasurements} measuredMm={measuredMm}/>}\n        <div className=\"drawingMarkerLayer\">"
new="{showMeasurements&&currentMeasurements.length>0&&<ReadOnlyDimensionOverlay targetRef={file.contentType.startsWith('image/')?imageRef:canvasRef} measurements={currentMeasurements} measuredMm={measuredMm}/>}\n        {showMeasurements&&currentAngles.length>0&&<ReadOnlyAngleOverlay targetRef={file.contentType.startsWith('image/')?imageRef:canvasRef} angles={currentAngles}/>}\n        <div className=\"drawingMarkerLayer\">"
assert old in a
